// SettingsServiceClient is a client for the aos.v1.SettingsService service.
type SettingsServiceClient interface {
	// Accepted Memory and the Agents' proposals.
	ListMemory(context.Context, *connect.Request[v1.ListMemoryRequest]) (*connect.Response[v1.ListMemoryResponse], error)
	// Saves an entry the user wrote.
	AddMemory(context.Context, *connect.Request[v1.AddMemoryRequest]) (*connect.Response[v1.AddMemoryResponse], error)
	// Accepts an Agent's proposal.
	AcceptMemory(context.Context, *connect.Request[v1.AcceptMemoryRequest]) (*connect.Response[v1.AcceptMemoryResponse], error)
	// Removes an entry or rejects a proposal.
	ForgetMemory(context.Context, *connect.Request[v1.ForgetMemoryRequest]) (*connect.Response[v1.ForgetMemoryResponse], error)
	// The Desktop's saved layout: window positions, theme and wallpaper. The
	// server stores it as an opaque JSON blob the client owns (PLAN.md §4.3).
	GetDesktopState(context.Context, *connect.Request[v1.GetDesktopStateRequest]) (*connect.Response[v1.GetDesktopStateResponse], error)
	SaveDesktopState(context.Context, *connect.Request[v1.SaveDesktopStateRequest]) (*connect.Response[v1.SaveDesktopStateResponse], error)
	// The settings that can change while AOS runs (PLAN.md §6.4), each with
	// where its value comes from.
	Get(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	// Saves one setting. An empty value removes the saved one, so the
	// environment's value, or the default, applies again.
	Update(context.Context, *connect.Request[v1.UpdateSettingRequest]) (*connect.Response[v1.UpdateSettingResponse], error)
	// Replaces the OpenAI API key (PLAN.md §7.7). It wins over the key from
	// .env, across restarts, until ClearApiKey. Only a hint (sk-…abcd) of any
	// key ever leaves aosd.
	SetApiKey(context.Context, *connect.Request[v1.SetApiKeyRequest]) (*connect.Response[v1.SetApiKeyResponse], error)
	// Goes back to the key from .env.
	ClearApiKey(context.Context, *connect.Request[v1.ClearApiKeyRequest]) (*connect.Response[v1.ClearApiKeyResponse], error)
}

